252	   * @param skipBlockIDCheck a true represents that the blockId verification
253	   *                         check should be skipped, false represents that
254	   *                         the blockId verification will be required
255	   * @return allocated but uncommitted locationInfos
256	   */
257	  public List<OmKeyLocationInfo> updateLocationInfoList(
258	      List<OmKeyLocationInfo> locationInfoList,
259	      boolean isMpu, boolean skipBlockIDCheck) {
260	    long latestVersion = getLatestVersionLocations().getVersion();
261	    OmKeyLocationInfoGroup keyLocationInfoGroup = getLatestVersionLocations();
262	
263	    keyLocationInfoGroup.setMultipartKey(isMpu);
264	
265	    // Compare user given block location against allocatedBlockLocations
266	    // present in OmKeyInfo.
267	    List<OmKeyLocationInfo> uncommittedBlocks;
268	    List<OmKeyLocationInfo> updatedBlockLocations;
269	    if (skipBlockIDCheck) {
270	      updatedBlockLocations = locationInfoList;
271	      uncommittedBlocks = new ArrayList<>();
272	    } else {
273	      Pair<List<OmKeyLocationInfo>, List<OmKeyLocationInfo>> verifiedResult =
274	          verifyAndGetKeyLocations(locationInfoList, keyLocationInfoGroup);
275	      updatedBlockLocations = verifiedResult.getLeft();
276	      uncommittedBlocks = verifiedResult.getRight();
277	    }
278	
279	    keyLocationInfoGroup.removeBlocks(latestVersion);
280	    // set each of the locationInfo object to the latest version
281	    updatedBlockLocations.forEach(omKeyLocationInfo -> omKeyLocationInfo
282	        .setCreateVersion(latestVersion));
283	    keyLocationInfoGroup.addAll(latestVersion, updatedBlockLocations);
284	
285	    return uncommittedBlocks;
286	  }
