288	  /**
289	   *  1. Verify committed KeyLocationInfos
290	   *  2. Find out the allocated but uncommitted KeyLocationInfos.
291	   *
292	   * @param locationInfoList committed KeyLocationInfos
293	   * @param keyLocationInfoGroup allocated KeyLocationInfoGroup
294	   * @return Pair of updatedOmKeyLocationInfo and uncommittedOmKeyLocationInfo
295	   */
296	  private Pair<List<OmKeyLocationInfo>, List<OmKeyLocationInfo>>
297	      verifyAndGetKeyLocations(
298	          List<OmKeyLocationInfo> locationInfoList,
299	          OmKeyLocationInfoGroup keyLocationInfoGroup) {
300	    // Only check ContainerBlockID here to avoid the mismatch of the pipeline
301	    // field and BcsId in the OmKeyLocationInfo, as the OmKeyInfoCodec ignores
302	    // the pipeline field by default and bcsId would be updated in Ratis mode.
303	    Map<ContainerBlockID, OmKeyLocationInfo> allocatedBlockLocations =
304	        new HashMap<>();
305	    for (OmKeyLocationInfo existingLocationInfo : keyLocationInfoGroup.
306	        getLocationList()) {
307	      ContainerBlockID existingBlockID = existingLocationInfo.getBlockID().
308	          getContainerBlockID();
309	      // The case of overwriting value should never happen
310	      allocatedBlockLocations.put(existingBlockID, existingLocationInfo);
311	    }
312	
313	    List<OmKeyLocationInfo> updatedBlockLocations = new ArrayList<>();
314	    for (OmKeyLocationInfo modifiedLocationInfo : locationInfoList) {
315	      ContainerBlockID modifiedContainerBlockId =
316	          modifiedLocationInfo.getBlockID().getContainerBlockID();
317	      if (allocatedBlockLocations.containsKey(modifiedContainerBlockId)) {
