  /**
   * Build the map of keys (keyed by their delete path key) whose blocks are
   * scheduled for deletion during the part commit.
   * <ul>
   *   <li>On overwrite, the previous part's blocks are scheduled for deletion
   *   under a delete path key derived from the old part's objectID.</li>
   *   <li>The allocated but uncommitted blocks are wrapped as a pseudo key
   *   and scheduled for deletion under a delete path key derived from a
   *   pseudo-object-ID (from the transaction log index), which is guaranteed
   *   to be unique and to differ from the objectID of any OmKeyInfo.</li>
   * </ul>
   * When an overwrite has uncommitted blocks, the two are kept as separate
   * entries because they use distinct delete path keys.
   *
   * @return map of delete path key to the keys scheduled for deletion
   */
  @SuppressWarnings("checkstyle:ParameterNumber")
  private Map<String, RepeatedOmKeyInfo> getKeysToDelete(
      OzoneManager ozoneManager, OMMetadataManager omMetadataManager,
      long trxnLogIndex, String multipartKey,
      OzoneManagerProtocolProtos.PartKeyInfo oldPartKeyInfo,
      OmKeyInfo omKeyInfo, List<OmKeyLocationInfo> uncommitted)
      throws IOException {
    Map<String, RepeatedOmKeyInfo> keysToDelete = new HashMap<>();

    // On overwrite of an existing part, schedule the old part's blocks for
    // deletion. multi-part key format is volumeName/bucketName/keyName/uploadId
    if (oldPartKeyInfo != null) {
      OmKeyInfo partKeyToBeDeleted =
          OmKeyInfo.getFromProtobuf(oldPartKeyInfo.getPartKeyInfo());
      RepeatedOmKeyInfo repeatedOmKeyInfo =
          getOldVersionsToCleanUp(partKeyToBeDeleted, trxnLogIndex);
      String delKeyName = omMetadataManager.getOzoneDeletePathKey(
          partKeyToBeDeleted.getObjectID(), multipartKey);
      keysToDelete.put(delKeyName, repeatedOmKeyInfo);
    }

    // Let the uncommitted blocks pretend as key's old version blocks which
    // will be deleted as RepeatedOmKeyInfo.
    OmKeyInfo pseudoKeyInfo =
        wrapUncommittedBlocksAsPseudoKey(uncommitted, omKeyInfo);
    if (pseudoKeyInfo != null) {
      // using pseudoObjId as objectId can be same in case of overwrite key
      long pseudoObjId = ozoneManager.getObjectIdFromTxId(trxnLogIndex);
      String delKeyName = omMetadataManager.getOzoneDeletePathKey(
          pseudoObjId, multipartKey);
      keysToDelete.computeIfAbsent(delKeyName,
          key -> new RepeatedOmKeyInfo()).addOmKeyInfo(pseudoKeyInfo);
    }

    return keysToDelete;
